        .value_or(Ref<std::vector<Result<T>>>());
  }

 private:
  /// The current batch of data.
  Ref<std::vector<Result<T>>> current_batch_;

  /// The underlying database iterator.
  Ref<IteratorBase> it_;

  /// The current index in the current batch.
  size_t ix_;
};

