/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }

  // Query from DailyTrafficView (which should contain the aggregated metrics)
  // The view implements the SQL query with strftime, COUNT(*), and COUNT(DISTINCT url)
  auto query_result = (read<std::vector<DailyTrafficView>> 
                      | order_by("visit_date"_c))(*conn_result);

  if (!query_result) {
    return {};
  }

  // Convert DailyTrafficView results to DailyTraffic format
  std::vector<DailyTraffic> metrics;
  metrics.reserve(query_result->size());

  for (const auto& row : *query_result) {
