#ifndef SQLGEN_TRANSPILATION_OPERATION_HPP_
#define SQLGEN_TRANSPILATION_OPERATION_HPP_

#include <string>
#include <type_traits>

#include "../Result.hpp"
#include "As.hpp"
#include "Condition.hpp"
