    // Using the vector-based in() from transpilation::conditions
    auto condition = transpilation::conditions::in(
        transpilation::Col<"doc_id", "">{}, 
        ids
    );

    // Get current timestamp
    auto now = std::chrono::system_clock::now();

    // Build the UPDATE query with SET clauses and WHERE condition
    auto update_query = update<Document>(
        is_deleted_col.set(1),
        deleted_at_col.set(now)
    ) | where(condition);

