#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Begin transaction
  auto trans = begin_transaction(conn);
  if (!trans) {
    return false;
  }

  // Step 1: Deduct from sender account (only if balance >= amount)
  // This ensures sufficient funds check
  auto trans_after_deduct = (
    update<Account>(Col<"balance">{}.set(Col<"balance">{} - amount))
    | where(Col<"account_id">{} == from_account_id && 
            Col<"balance">{} >= amount)
  )(trans);

  if (!trans_after_deduct) {
    return false;  // Transaction will auto-rollback on destruction
  }

  // Step 2: Add to receiver account
  auto trans_after_add = (
    update<Account>(Col<"balance">{}.set(Col<"balance">{} + amount))
    | where(Col<"account_id">{} == to_account_id)
  )(trans_after_deduct);

  if (!trans_after_add) {
    return false;  // Transaction will auto-rollback on destruction
  }

  // Step 3: Commit transaction
  auto result = commit(trans_after_add);

  return result.has_value();
}

}  // namespace transaction_transfer_funds
