#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

#include "eas_common.hpp"

namespace update_eas_table {

void update_eas_table() {
  design_eas_database_with_major();

  sqlgen::sqlite::connect(db_path)
      .and_then([](auto&& conn) {
        // Task 1: Add a new column Grade to the Score table
        // CHAR(1) NOT NULL - need DEFAULT for SQLite when adding NOT NULL to existing table
        return sqlgen::exec(conn, "ALTER TABLE Score ADD COLUMN Grade CHAR(1) NOT NULL DEFAULT 'A';");
      })
      .and_then([](auto&& conn) {
        // Task 2: Modify the Age column type in Student table to INT allowing null
        // For SQLite, we need to recreate the table to modify column type
        return sqlgen::exec(conn, "PRAGMA foreign_keys = OFF;");
      })
      .and_then([](auto&& conn) {
        return sqlgen::exec(conn, 
          "CREATE TABLE Student_new ("
          "SNo VARCHAR(10) PRIMARY KEY, "
          "SName VARCHAR(30), "
          "Sex INT DEFAULT 1, "
          "Birthday DATETIME, "
          "Major INT, "
          "Scorses REAL, "
          "Remark TEXT, "
          "Age INT"
          ");");
      })
      .and_then([](auto&& conn) {
        return sqlgen::exec(conn, 
          "INSERT INTO Student_new (SNo, SName, Sex, Birthday, Major, Scorses, Remark, Age) "
          "SELECT SNo, SName, Sex, Birthday, Major, Scorses, Remark, Age FROM Student;");
      })
      .and_then([](auto&& conn) {
        return sqlgen::exec(conn, "DROP TABLE Student;");
      })
      .and_then([](auto&& conn) {
        return sqlgen::exec(conn, "ALTER TABLE Student_new RENAME TO Student;");
      })
      .and_then([](auto&& conn) {
        return sqlgen::exec(conn, "PRAGMA foreign_keys = ON;");
      })
      // Task 3: Drop the Major table
      .and_then(sqlgen::drop<Major>)
      .value();
}

} // namespace update_eas_table

