namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  static constexpr bool is_view = true;
  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  using namespace sqlgen;

  // Connect to SQLite database
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  // Build the SELECT query for the view
  // SELECT p.name as product_name, SUM(s.quantity) as total_quantity, SUM(s.amount) as total_revenue
  // FROM Sale s
  // JOIN Product p ON s.product_id = p.product_id
  // GROUP BY p.name
  auto query = select_from<Sale, "s">(
    col<"name", "p"> | as<"product_name">,
    sum(col<"quantity", "s">) | as<"total_quantity">,
    sum(col<"amount", "s">) | as<"total_revenue">
  )
  | inner_join<Product, "p">(col<"product_id", "s"> == col<"product_id", "p">)
  | group_by(col<"name", "p">);

  // Create the view with IF NOT EXISTS (SQLite doesn't support OR REPLACE for views)
  auto result = (create_as<SalesSummary>(query) | if_not_exists)(conn_result);

  return result.has_value();
}

}  // namespace schema_create_view_sales_summary
