namespace mathematical_operations_analysis {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int quantity;
  double discount_rate;
};

struct MathAnalysis {
  int product_id;
  std::string name;
  double abs_price;
  double ceil_price;
  double floor_price;
  double rounded_price;
  double exp_discount;
  double ln_price;
  double log2_quantity;
  double sin_discount;
  double cos_discount;
  double tan_discount;
  double sqrt_quantity;
};

/**
 * Insert products into a temporary SQLite table and run a SELECT that computes
 * various mathematical expressions, returning results as std::vector<MathAnalysis>.
 */
std::vector<MathAnalysis> analyze_mathematical_operations(const std::vector<Product>& products) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  if (!conn) {
    return {};
  }

  // Execute SELECT query with mathematical operations
  auto result = select_from<Product>(
    "product_id"_c,
    "name"_c,
    abs("price"_c) | as<"abs_price">,
    ceil("price"_c) | as<"ceil_price">,
    floor("price"_c) | as<"floor_price">,
    round("price"_c, 2) | as<"rounded_price">,
    exp("discount_rate"_c / 100.0) | as<"exp_discount">,
    ln("price"_c) | as<"ln_price">,
    log2(cast<double>("quantity"_c)) | as<"log2_quantity">,
    sin("discount_rate"_c) | as<"sin_discount">,
    cos("discount_rate"_c) | as<"cos_discount">,
    tan("discount_rate"_c) | as<"tan_discount">,
    sqrt(cast<double>("quantity"_c)) | as<"sqrt_quantity">
  ).execute(conn);

  std::vector<MathAnalysis> analyses;
  for (const auto& row : result) {
    analyses.push_back({
      row.product_id,
      row.name,
      row.abs_price,
      row.ceil_price,
      row.floor_price,
      row.rounded_price,
      row.exp_discount,
      row.ln_price,
      row.log2_quantity,
      row.sin_discount,
      row.cos_discount,
      row.tan_discount,
      row.sqrt_quantity
    });
  }

  return analyses;
}

} // namespace mathematical_operations_analysis
