namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return {};
  }
  auto conn = *conn_result;

  // Write items to OrderItem table
  auto write_result = sqlgen::write(conn, items);
  if (!write_result) {
    return {};
  }

  // Define column references
  constexpr auto item_id = sqlgen::col<"item_id">;
  constexpr auto order_id = sqlgen::col<"order_id">;
  constexpr auto product_id = sqlgen::col<"product_id">;
  constexpr auto unit_price = sqlgen::col<"unit_price">;
  constexpr auto quantity = sqlgen::col<"quantity">;
  constexpr auto discount_rate = sqlgen::col<"discount_rate">;
  constexpr auto tax_rate = sqlgen::col<"tax_rate">;

  // Calculate metrics using arithmetic operations
  // gross_total = unit_price * quantity
  auto gross_total = (unit_price * quantity).as<"gross_total">();

  // discounted_total = unit_price * quantity * (1 - discount_rate/100)
  // Note: We handle the COALESCE logic by using operations directly
  auto discounted_total = (unit_price * quantity * (1.0 - discount_rate / 100.0)).as<"discounted_total">();

  // final_total = discounted_total * (1 + tax_rate/100)
  auto final_total = (unit_price * quantity * (1.0 - discount_rate / 100.0) * (1.0 + tax_rate / 100.0)).as<"final_total">();

  // unit_cost = unit_price * quantity / quantity (essentially unit_price)
  auto unit_cost = (unit_price * quantity / quantity).as<"unit_cost">();

  // quantity_group = quantity % 10
  auto quantity_group = (quantity % 10).as<"quantity_group">();

  // estimated_profit = unit_price * 0.3
  auto estimated_profit = (unit_price * 0.3).as<"estimated_profit">();

  // Execute the query with all calculated fields
  auto query = sqlgen::select_from<OrderItem>(
    item_id,
    order_id,
    product_id,
    unit_price,
    quantity,
    discount_rate,
    tax_rate,
    gross_total,
    discounted_total,
    final_total,
    unit_cost,
    quantity_group,
    estimated_profit
  ) | sqlgen::to<std::vector<OrderMetrics>>;

  auto result = query(conn);
  if (!result) {
    return {};
  }

  return *result;
}

}  // namespace calculate_order_metrics
