  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  auto c = conn.value();

  // Enable foreign key constraints (required for CASCADE in SQLite)
  auto fk_result = c->execute("PRAGMA foreign_keys = ON;");
  if (!fk_result) {
    return false;
  }

  // Create Parent table
  auto parent_table = create_table<Parent>{.if_not_exists_ = true};
  auto result = parent_table(c);
  if (!result) {
    return false;
  }

  // Create Child table with foreign key constraint
  auto child_table = create_table<Child>{.if_not_exists_ = true};
  result = child_table(result.value());
  if (!result) {
    return false;
  }

  // Insert parent record
  Parent parent{.parent_id = 1, .name = "TestParent"};
  result = insert(parent)(result.value());
  if (!result) {
    return false;
  }

  // Insert child records with same parent_id
  Child child1{.child_id = 1, .parent_id = 1, .note = "Child1"};
  Child child2{.child_id = 2, .parent_id = 1, .note = "Child2"};

  result = insert(child1)(result.value());
  if (!result) {
    return false;
  }

  result = insert(child2)(result.value());
  if (!result) {
    return false;
  }

  // Delete parent record - should cascade delete children
  auto delete_op = delete_from<Parent> | where("parent_id"_c == 1);
  result = delete_op(result.value());
  if (!result) {
    return false;
