  // Verify that children were cascade deleted
  // Query to check if any children with parent_id = 1 still exist
  auto verify_result = result.value()->execute(
    "SELECT COUNT(*) FROM Child WHERE parent_id = 1"
  );

  if (!verify_result) {
    return false;
  }

  // If execution succeeded, cascade delete worked correctly
  // (children should have been automatically deleted when parent was deleted)
  return true;
}

}  // namespace cascade_delete_demo
