namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the FULL JOIN query
  // Select supplier name and product name from Supplier table aliased as 's'
  // Full join with Product table aliased as 'p' on supplier_id
  auto query = sqlgen::select_from<Supplier, "s">(
      sqlgen::col<"name", "s">.as<"supplier_name">(),
      sqlgen::col<"name", "p">.as<"product_name">()
  ) | sqlgen::full_join<Product, "p">(
      sqlgen::col<"supplier_id", "s"> == sqlgen::col<"supplier_id", "p">
  ) | sqlgen::to<std::vector<SupProd>>;

  // Execute the query
  auto result = query(conn);

  // Return the results or empty vector on error
  if (result) {
    return *result;
  } else {
    return {};
  }
}

