#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <sstream>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  using namespace sqlgen::literals;

  // Helper to escape SQL strings
  auto escape = [](const std::string& s) {
    std::string result;
    for (char c : s) {
      if (c == '\'') result += "''";
      else result += c;
    }
    return result;
  };

  // Connect to database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    return JoinAnalysis{};
  }

  // Drop and create tables
  conn = sqlgen::exec(conn, "DROP TABLE IF EXISTS Employee");
  conn = sqlgen::exec(conn, "DROP TABLE IF EXISTS Department");

  conn = sqlgen::exec(conn, R"(
    CREATE TABLE Department (
      department_id INTEGER PRIMARY KEY,
      department_name TEXT NOT NULL,
      location TEXT
    )
  )");

  conn = sqlgen::exec(conn, R"(
    CREATE TABLE Employee (
      employee_id INTEGER PRIMARY KEY,
      department_id INTEGER,
      first_name TEXT NOT NULL,
      last_name TEXT NOT NULL,
      salary REAL NOT NULL
    )
  )");

  if (!conn) {
    return JoinAnalysis{};
  }

  // Insert departments
  for (const auto& dept : depts) {
    std::ostringstream oss;
    oss << "INSERT INTO Department (department_id, department_name, location) VALUES ("
        << *dept.department_id << ", '"
        << escape(dept.department_name) << "', '"
        << escape(dept.location) << "')";
    conn = sqlgen::exec(conn, oss.str());
    if (!conn) return JoinAnalysis{};
  }

  // Insert employees
  for (const auto& emp : emps) {
    std::ostringstream oss;
    oss << "INSERT INTO Employee (employee_id, department_id, first_name, last_name, salary) VALUES ("
        << *emp.employee_id << ", "
        << emp.department_id << ", '"
        << escape(emp.first_name) << "', '"
        << escape(emp.last_name) << "', "
        << emp.salary << ")";
    conn = sqlgen::exec(conn, oss.str());
    if (!conn) return JoinAnalysis{};
  }

  JoinAnalysis analysis;

  // INNER JOIN: Department INNER JOIN Employee
  auto inner_query = sqlgen::select_from<Department, "t1">(
    "department_name"_t1 | sqlgen::as<"department_name">,
    "first_name"_t2 | sqlgen::as<"first_name">,
    "last_name"_t2 | sqlgen::as<"last_name">,
    "salary"_t2 | sqlgen::as<"salary">
  ) | sqlgen::inner_join<Employee, "t2">("department_id"_t1 == "department_id"_t2)
    | sqlgen::to<std::vector<JoinResult>>;

  auto inner_result = inner_query(conn);
  if (inner_result) {
    analysis.inner_join_results = *inner_result;
  }

  // LEFT JOIN: Employee LEFT JOIN Department
  auto left_query = sqlgen::select_from<Employee, "t1">(
    "department_name"_t2 | sqlgen::as<"department_name">,
    "first_name"_t1 | sqlgen::as<"first_name">,
    "last_name"_t1 | sqlgen::as<"last_name">,
    "salary"_t1 | sqlgen::as<"salary">
  ) | sqlgen::left_join<Department, "t2">("department_id"_t1 == "department_id"_t2)
    | sqlgen::to<std::vector<JoinResult>>;

  auto left_result = left_query(conn);
  if (left_result) {
    analysis.left_join_results = *left_result;
  }

  // RIGHT JOIN: Employee RIGHT JOIN Department
  auto right_query = sqlgen::select_from<Employee, "t1">(
    "department_name"_t2 | sqlgen::as<"department_name">,
    "first_name"_t1 | sqlgen::as<"first_name">,
    "last_name"_t1 | sqlgen::as<"last_name">,
    "salary"_t1 | sqlgen::as<"salary">
  ) | sqlgen::right_join<Department, "t2">("department_id"_t1 == "department_id"_t2)
    | sqlgen::to<std::vector<JoinResult>>;

  auto right_result = right_query(conn);
  if (right_result) {
    analysis.right_join_results = *right_result;
  }

  // FULL JOIN: Employee FULL JOIN Department
  auto full_query = sqlgen::select_from<Employee, "t1">(
    "department_name"_t2 | sqlgen::as<"department_name">,
    "first_name"_t1 | sqlgen::as<"first_name">,
    "last_name"_t1 | sqlgen::as<"last_name">,
    "salary"_t1 | sqlgen::as<"salary">
  ) | sqlgen::full_join<Department, "t2">("department_id"_t1 == "department_id"_t2)
    | sqlgen::to<std::vector<JoinResult>>;

  auto full_result = full_query(conn);
  if (full_result) {
    analysis.full_join_results = *full_result;
  }

  return analysis;
}

}  // namespace analyze_department_employees
