    return SelectFrom<TableOrQueryType, AliasType, FieldsType, JoinsType,
                      WhereType, GroupByType, OrderByType, Limit, ToType>{
        .fields_ = _s.fields_,
        .from_ = _s.from_,
        .joins_ = _s.joins_,
        .where_ = _s.where_,
        .limit_ = _limit};
